    panels = [
        [row[c:c + 5] for row in grid[r:r + 5]]
        for r in (0, 6)
        for c in (0, 6)
    ]

    def normalize(panel):
        pts = [(r, c) for r in range(5) for c in range(5)
               if panel[r][c] not in (6, 7)]
        if not pts:
            return [row[:] for row in panel]

        rmin = min(r for r, c in pts)
        rmax = max(r for r, c in pts)
        cmin = min(c for r, c in pts)
        cmax = max(c for r, c in pts)

        def nearest_int(x):
            return int(x + 0.5) if x >= 0 else int(x - 0.5)

        dr = nearest_int(2 - (rmin + rmax) / 2)
        dc = nearest_int(2 - (cmin + cmax) / 2)
        result = [[7] * 5 for _ in range(5)]
        for r, c in pts:
            result[r + dr][c + dc] = panel[r][c]
        return result

    panels = [normalize(p) for p in panels]
    panels.sort(key=lambda p: sum(v not in (6, 7) for row in p for v in row))

    out = [[7] * 23 for _ in range(5)]
    for i, panel in enumerate(panels):
        c0 = 6 * i
        for r in range(5):
            out[r][c0:c0 + 5] = panel[r]
            if i < 3:
                out[r][c0 + 5] = 6
